// checkout-conversion-fix.js
// Brainstem directive: paidEvents still zero. Ensure checkout flow triggers revenue event.

const revenueModule = require('./revenue-module');

module.exports = function attachCheckoutConversion(app) {
  app.post('/api/checkout/complete', async (req, res) => {
    try {
      const { orderId, amount, currency } = req.body;
      if (!orderId || !amount) {
        return res.status(400).json({ error: 'Missing orderId or amount' });
      }
      // Record revenue event
      await revenueModule.recordSale({
        orderId,
        amount: parseFloat(amount),
        currency: currency || 'USD',
        timestamp: new Date().toISOString()
      });
      return res.json({ success: true, paid: true });
    } catch (err) {
      console.error('Checkout conversion error:', err);
      return res.status(500).json({ error: 'Internal error' });
    }
  });
};
